567	/**
568	 * Simple local similarity computation (Jaccard-like)
569	 */
570	function computeLocalSimilarity(query: string, content: string): number {
571	  const queryWords = new Set(query.toLowerCase().split(/\s+/));
572	  const contentWords = new Set(content.toLowerCase().split(/\s+/));
573	  const intersection = [...queryWords].filter(w => contentWords.has(w)).length;
574	  const union = new Set([...queryWords, ...contentWords]).size;
575	  return union > 0 ? (intersection / union) * 0.3 + 0.7 : 0.7;
576	}
