314	   */
315	  async drain(): Promise<void> {
316	    this.isShuttingDown = true;
317	    this.logger.info('Draining connection pool');
318	
319	    // Reject all waiting clients
320	    while (this.waitingClients.length > 0) {
321	      const client = this.waitingClients.shift();
322	      client?.reject(new Error('Connection pool is draining'));
323	    }
324	
325	    // Wait for busy connections to be released
326	    const maxWait = 10000; // 10 seconds
327	    const startTime = Date.now();
328	
329	    while (Date.now() - startTime < maxWait) {
330	      let busyCount = 0;
331	      for (const connection of this.connections.values()) {
332	        if (connection.state === 'busy') busyCount++;
333	      }
334	
335	      if (busyCount === 0) break;
336	
337	      await new Promise((resolve) => setTimeout(resolve, 100));
338	    }
339	
340	    this.logger.info('Connection pool drained');
341	  }
